--!strict
-- Journals the callbacks of one script slot under its Label (MultiScript.scene), so an entity with several Tracer slots
-- shows the order in which its slots receive each callback (Architecture §11.3; Docs/Decisions/0031-m20-contract.md
-- decision 17).
local Journal = require("./Journal")

export type Tracer = ScriptInstance & {
	Label: string,
	FixedSteps: number,
}

local Tracer = {}

Tracer.Fields = {
	Label = Field.String("", { Tooltip = "The name the journal records this slot's instance under" }),
}

function Tracer.OnCreate(self: Tracer)
	self.FixedSteps = 0
	Journal.Record(self.Label, "create")
end

function Tracer.OnEnable(self: Tracer)
	Journal.Record(self.Label, "enable")
end

function Tracer.OnDisable(self: Tracer)
	Journal.Record(self.Label, "disable")
end

function Tracer.OnDestroy(self: Tracer)
	Journal.Record(self.Label, "destroy")
end

function Tracer.OnFixedUpdate(self: Tracer, dt: number)
	self.FixedSteps += 1
	Journal.Record(self.Label, "fixed")
end

function Tracer.OnCollisionEnter(self: Tracer, other: Entity)
	Journal.Record(self.Label, "hit:" .. other.Name)
end

return Script.Define("Tracer", Tracer)

--!strict
-- Adds Step to its total every fixed step (MultiScript.scene). Two slots of one entity may both hold it, each its own
-- instance with its own fields and state (Docs/Decisions/0031-m20-contract.md decision 17).
export type Counter = ScriptInstance & {
	Label: string,
	Step: number,
	Total: number,
}

local Counter = {}

Counter.Fields = {
	Label = Field.String("", { Tooltip = "The name the MultiScript suite tells this instance by" }),
	Step = Field.Integer(1, { Min = 1, Max = 100, Tooltip = "How much the total grows each fixed step" }),
}

function Counter.OnCreate(self: Counter)
	self.Total = 0
end

function Counter.OnFixedUpdate(self: Counter, dt: number)
	self.Total += self.Step
end

return Script.Define("Counter", Counter)

--!strict
-- A script slot that faults in its next fixed step once a test arms it (MultiScript.scene's Hero): the fault disables
-- this slot's instance only, and the entity's other slots keep running (Docs/Decisions/0031-m20-contract.md decision 17).
export type Fragile = ScriptInstance & {
	Armed: boolean,
	Steps: number,
}

local Fragile = {}

function Fragile.OnCreate(self: Fragile)
	self.Armed = false
	self.Steps = 0
end

function Fragile.OnFixedUpdate(self: Fragile, dt: number)
	self.Steps += 1
	if self.Armed then
		self.Armed = false
		error("deliberate slot fault")
	end
end

return Script.Define("Fragile", Fragile)

--!strict
-- Moves its entity along X by the MoveX action (MultiScript.scene's Pilot, slot 0). The Trail of the next slot reads the
-- position this slot wrote in the same fixed step (Docs/Decisions/0031-m20-contract.md decision 17).
export type Mover = ScriptInstance & {
	Speed: number,
}

local Mover = {}

Mover.Fields = {
	Speed = Field.Number(1, { Min = 0, Max = 20, Tooltip = "Metres per second at full MoveX" }),
}

function Mover.OnFixedUpdate(self: Mover, dt: number)
	self.Entity.Transform:Translate(vector.create(Input.GetAxis("MoveX") * self.Speed * dt, 0, 0))
end

return Script.Define("Mover", Mover)

--!strict
-- Stretches its entity along X by its distance from the origin (MultiScript.scene's Pilot, slot 1). It runs after the
-- Mover of slot 0 in every fixed step (slot order), so the scale always matches the position of the same step, which the
-- state hash and the MultiScript replay's checkpoints see (Docs/Decisions/0031-m20-contract.md decision 17).
export type Trail = ScriptInstance & {
	Gain: number,
	Samples: number,
}

local Trail = {}

Trail.Fields = {
	Gain = Field.Number(0.5, { Min = 0, Max = 10, Tooltip = "Scale added per metre from the origin" }),
}

function Trail.OnCreate(self: Trail)
	self.Samples = 0
end

function Trail.OnFixedUpdate(self: Trail, dt: number)
	self.Samples += 1
	local transform = self.Entity.Transform
	transform.Scale = vector.create(1 + math.abs(transform.Translation.x) * self.Gain, 1, 1)
end

return Script.Define("Trail", Trail)
